import android.util.Base64;import android.util.Base64OutputStream;import java.io.*;import java.util.Arrays;
public final class CloseNegative{public static void main(String[]args)throws Exception{var sink=new ByteArrayOutputStream();var out=new Base64OutputStream(sink,Base64.NO_PADDING,false);out.write('A');out.write('Q');out.close();if(!Arrays.equals(sink.toByteArray(),new byte[]{1}))throw new AssertionError("Original decoder lost its final partial tuple");out.close();if(!Arrays.equals(sink.toByteArray(),new byte[]{1,1}))throw new AssertionError("Original repeated finish changed its buffered-tail behavior");}}
